import sys
from collections import defaultdict, deque

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    t = int(next(iterator))
    results = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        adj = [[] for _ in range(n + 1)]
        in_degree = [0] * (n + 1)
        edges = []

        for i in range(m):
            typ = int(next(iterator))
            u = int(next(iterator))
            v = int(next(iterator))

            edges.append((typ, u, v))

            if typ == 1:
                adj[u].append(v)
                in_degree[v] += 1

        # Topological sort using Kahn's algorithm
        queue = deque()
        topo_order = []

        for i in range(1, n + 1):
            if in_degree[i] == 0:
                queue.append(i)

        while queue:
            u = queue.popleft()
            topo_order.append(u)

            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        if len(topo_order) != n:
            results.append("NO")
            continue

        # Map vertex to its position in topological order
        pos = [0] * (n + 1)
        for idx, node in enumerate(topo_order):
            pos[node] = idx

        results.append("YES")
        output_edges = []

        for typ, u, v in edges:
            if typ == 1:
                output_edges.append(f"{u} {v}")
            else:
                if pos[u] < pos[v]:
                    output_edges.append(f"{u} {v}")
                else:
                    output_edges.append(f"{v} {u}")

        results.extend(output_edges)

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
